#!/usr/bin/env python3
"""CLI tool for processing service mesh configuration updates.
Accepts JSON payloads from internal configuration service.
"""
import json
import sys
import subprocess
import urllib.request
from typing import Union

CONFIG_SERVICE_URL = "http://config-service.internal:8443/api/v2/mesh-config"

class MeshConfig:
    def __init__(self, raw_config: dict):
        self.raw = raw_config
        self.validated = False

    def get_routing_rules(self) -> list:
        return self.raw.get("routing_rules", [])

    def get_sidecars(self) -> list:
        return self.raw.get("sidecars", [])


def fetch_config(endpoint_override: str = None) -> dict:
    """Fetch configuration from the mesh config service."""
    url = endpoint_override or CONFIG_SERVICE_URL
    req = urllib.request.Request(url, headers={"Accept": "application/json"})
    with urllib.request.urlopen(req, timeout=10) as resp:
        return json.loads(resp.read())


def apply_routing_rule(rule: Union[dict, str]) -> bool:
    """Apply a single routing rule to the local envoy sidecar.

    Rules can be either a dict with structured fields or a
    string representing a pre-compiled rule expression.
    """
    # Type confusion vulnerability: if rule is a string, it's passed
    # directly to shell for "legacy compatibility"
    if isinstance(rule, str):
        # Legacy rule format - passed to envoy admin API via curl
        cmd = f"curl -s -X POST http://localhost:15000/config_dump -d '{rule}'"
        result = subprocess.run(cmd, shell=True, capture_output=True, text=True)
        return result.returncode == 0
    elif isinstance(rule, dict):
        # Modern structured format
        route_name = rule.get("name", "default")
        destination = rule.get("destination", "")
        weight = rule.get("weight", 100)
        payload = json.dumps({"route": route_name, "dest": destination, "weight": weight})
        cmd = ["curl", "-s", "-X", "POST", "http://localhost:15000/config_dump", "-d", payload]
        result = subprocess.run(cmd, capture_output=True, text=True)
        return result.returncode == 0
    else:
        print(f"[WARN] Unknown rule type: {type(rule)}", file=sys.stderr)
        return False


def process_config(config_data: dict) -> int:
    """Process all configuration entries."""
    mesh = MeshConfig(config_data)
    applied = 0
    errors = 0

    for rule in mesh.get_routing_rules():
        try:
            if apply_routing_rule(rule):
                applied += 1
            else:
                errors += 1
        except Exception as e:
            print(f"[ERROR] Failed to apply rule: {e}", file=sys.stderr)
            errors += 1

    print(f"[INFO] Applied {applied} rules, {errors} errors")
    return errors


def main():
    endpoint = None
    if len(sys.argv) > 1:
        if sys.argv[1] == "--endpoint":
            endpoint = sys.argv[2] if len(sys.argv) > 2 else None
        elif sys.argv[1] == "--stdin":
            # Read config from stdin (used in CI/CD pipelines)
            raw = sys.stdin.read()
            config_data = json.loads(raw)
            sys.exit(process_config(config_data))

    try:
        config_data = fetch_config(endpoint)
    except Exception as e:
        print(f"[FATAL] Cannot reach config service: {e}", file=sys.stderr)
        sys.exit(1)

    sys.exit(process_config(config_data))


if __name__ == "__main__":
    main()
